/* =====================================================================
   2. SMALL HELPERS
   ===================================================================== */
const $ = (selector, root = document) => root.querySelector(selector);
const $$ = (selector, root = document) => Array.from(root.querySelectorAll(selector));
const wrap = (index, length) => (index + length) % length;
const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
const isTouch = () => window.matchMedia('(hover: none)').matches;
const FLIP_MS = 1000;                                          // must match the .leaf transition in style.css

/* load every photo early so page turns and fades never show an empty page */
Object.values(PHOTOS).flat().forEach(photo => { const preload = new Image(); preload.src = photo.src; });

/* Show one photo inside a ".pf" frame. Fades out, swaps the image, fades in.
   If the file is missing, the frame gets "missing" and shows the placeholder. */
function showPhoto(frame, photo, instant = false) {
  const img = $('img', frame);
  const swap = () => {
    frame.classList.remove('missing', 'end');
    img.onload = () => frame.classList.remove('fade-out');
    img.onerror = () => {
      if (photo.fallback && img.getAttribute('src') !== photo.fallback) { img.src = photo.fallback; return; }   // not in the folder? try next to the HTML file
      frame.classList.add('missing'); frame.classList.remove('fade-out');
    };
    img.alt = photo.alt || '';
    img.src = photo.src;
  };
  if (instant || reduceMotion) { swap(); return; }
  frame.classList.add('fade-out');
  setTimeout(swap, 170);
}

/* Swipe left/right on an element (phones and tablets). */
function addSwipe(element, onNext, onPrev) {
  let startX = null;
  element.addEventListener('pointerdown', e => { startX = e.clientX; });
  element.addEventListener('pointerup', e => {
    if (startX === null) return;
    const dx = e.clientX - startX;
    startX = null;
    if (Math.abs(dx) > 50) (dx < 0 ? onNext : onPrev)();
  });
  element.addEventListener('pointercancel', () => { startX = null; });
}

/* Reusable looping gallery used by the camera and the tablet. */
function makeLoopGallery({ photos, frame, counter, label, prev, next }) {
  let index = 0;
  function go(i, instant = false) {
    index = wrap(i, photos.length);
    showPhoto(frame, photos[index], instant);
    counter.textContent = label(index + 1, photos.length);
  }
  prev.addEventListener('click', () => go(index - 1));
  next.addEventListener('click', () => go(index + 1));
  go(0, true);
  return { next: () => go(index + 1), prev: () => go(index - 1), reset: () => go(0, true), go, index: () => index };
}

/* =====================================================================
   3. SKETCHBOOK  (two facing pages, one full-page photo on each;
                   the page turns around the spine like a real book)
   ===================================================================== */
const sketchbook = (() => {
  const photos = PHOTOS.sketchbook;
  const pages = $('#sk-pages');
  const left = $('#page-left'), right = $('#page-right');
  const leaf = $('#leaf'), leafFront = $('#leaf-front'), leafBack = $('#leaf-back');
  const count = $('#sk-count'), prevBtn = $('#sk-prev'), nextBtn = $('#sk-next');
  const lastSpread = Math.max(0, Math.ceil(photos.length / 2) - 1);
  let spread = 0, busy = false;

  /* fill one page with photo number "index" (0 = first). Past the last photo it becomes "The end". */
  function fill(frame, index, side) {
    frame.dataset.side = side;
    const number = $('.pgnum', frame);
    if (photos[index]) {
      showPhoto(frame, photos[index], true);
      number.textContent = index + 1;
    } else {
      frame.classList.remove('missing');
      frame.classList.add('end');
      number.textContent = '';
    }
  }

  function updateControls() {
    const first = spread * 2;
    const a = first + 1, b = Math.min(first + 2, photos.length);
    count.textContent = (b > a ? `Pages ${a}\u2013${b}` : `Page ${a}`) + ` of ${photos.length}`;
    prevBtn.disabled = spread === 0;
    nextBtn.disabled = spread === lastSpread;
  }

  function render() {
    fill(left, spread * 2, 'l');
    fill(right, spread * 2 + 1, 'r');
    updateControls();
  }

  function flip(direction) {
    if (busy) return;
    const target = spread + (direction === 'next' ? 1 : -1);
    if (target < 0 || target > lastSpread) return;
    if (reduceMotion || window.matchMedia('(max-width: 700px)').matches) {   // phones show the pages stacked: a simple fade instead of the 3D turn
      spread = target; render();
      pages.classList.remove('fade-turn'); void pages.offsetWidth; pages.classList.add('fade-turn');
      return;
    }
    busy = true;
    const first = spread * 2, newFirst = target * 2;
    if (direction === 'next') {            // the right page lifts and turns over to become the new left page
      leaf.className = 'leaf right';
      fill(leafFront, first + 1, 'r');
      fill(leafBack, newFirst, 'l');
      fill(right, newFirst + 1, 'r');      // the new right page waits underneath
    } else {                               // the left page turns back over to become the new right page
      leaf.className = 'leaf left';
      fill(leafFront, first, 'l');
      fill(leafBack, newFirst + 1, 'r');
      fill(left, newFirst, 'l');           // the new left page waits underneath
    }
    leaf.hidden = false;
    void leaf.offsetWidth;                 // let the browser draw the start position first
    leaf.classList.add('flipping');
    setTimeout(() => {
      spread = target;
      render();
      leaf.hidden = true;
      leaf.className = 'leaf';
      busy = false;
    }, FLIP_MS + 40);
  }

  const next = () => flip('next');
  const prev = () => flip('prev');
  nextBtn.addEventListener('click', next);
  prevBtn.addEventListener('click', prev);
  addSwipe(pages, next, prev);
  render();
  return { next, prev, reset: () => { if (!busy) { spread = 0; render(); } } };
})();

/* =====================================================================
   4. CAMERA  (browse with the dial, press the shutter for a flash)
   ===================================================================== */
const camera = (() => {
  const gallery = makeLoopGallery({
    photos: PHOTOS.camera, frame: $('#cam-frame'), counter: $('#cam-count'),
    label: (n, total) => `${n}/${total}`, prev: $('#cam-prev'), next: $('#cam-next')
  });
  const screen = $('#cam-frame');
  const lamp = $('#lamp');
  $('#shutter').addEventListener('click', () => {               // just an animation, never uses the real camera
    screen.classList.remove('shot'); lamp.classList.remove('on');
    void screen.offsetWidth;
    screen.classList.add('shot'); lamp.classList.add('on');
  });
  addSwipe(screen, gallery.next, gallery.prev);
  return gallery;
})();

/* =====================================================================
   5. TABLET
   ===================================================================== */
const tablet = (() => {
  const gallery = makeLoopGallery({
    photos: PHOTOS.tablet, frame: $('#tab-frame'), counter: $('#tab-count'),
    label: (n, total) => `Photo ${n} of ${total}`, prev: $('#tab-prev'), next: $('#tab-next')
  });
  const frame = $('#tab-frame');
  addSwipe(frame, gallery.next, gallery.prev);
  frame.style.touchAction = 'manipulation';                       // a double tap should open the photo, not zoom the page
  frame.title = 'Double-tap to view full size';
  let lastTap = { time: 0, x: 0, y: 0 }, down = null;
  frame.addEventListener('pointerdown', e => { down = { x: e.clientX, y: e.clientY }; });
  frame.addEventListener('pointerup', e => {
    if (e.target.closest('.t-nav, .desc-btn') || !down) return;   // ignore the arrows
    const moved = Math.hypot(e.clientX - down.x, e.clientY - down.y);
    down = null;
    if (moved > 15) { lastTap.time = 0; return; }                  // that was a swipe, not a tap
    const now = Date.now();
    const close = Math.hypot(e.clientX - lastTap.x, e.clientY - lastTap.y) < 40;
    if (now - lastTap.time < 350 && close) {
      lastTap.time = 0;
      openLightbox(gallery.index(), frame, 'tablet');
    } else {
      lastTap = { time: now, x: e.clientX, y: e.clientY };
    }
  });
  return gallery;
})();

/* =====================================================================
   6. POLAROIDS  (scrolling row; double-click or tap for the full photo)
   ===================================================================== */
const polaroids = (() => {
  const photos = PHOTOS.polaroid;
  const track = $('#pol-track');
  const counter = $('#pol-count');
  const prevBtn = $('#pol-prev');
  const nextBtn = $('#pol-next');
  const cards = [];
  let current = 0;

  photos.forEach((photo, i) => {
    const card = document.createElement('figure');
    card.className = 'pol-card';
    card.tabIndex = 0;
    card.setAttribute('role', 'button');
    card.setAttribute('aria-label', `Polaroid ${i + 1} of ${photos.length}. Double-click to view full size.`);
    card.innerHTML = '<span class="tape" aria-hidden="true"></span>' +
      '<div class="pf pol-photo"><img alt=""><div class="ph">Insert your photo here</div></div><figcaption></figcaption>';
    $('figcaption', card).textContent = photo.caption || '';
    showPhoto($('.pf', card), photo, true);
    card.addEventListener('dblclick', () => openLightbox(i, card));          // desktop: double-click
    card.addEventListener('click', () => {
      if (isTouch()) openLightbox(i, card);                                   // phones: a tap
      else centerOn(i);                                                       // desktop: single click centers it
    });
    card.addEventListener('keydown', e => {
      if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); openLightbox(i, card); }
    });
    track.append(card);
    cards.push(card);
  });

  function centerOn(i, smooth = true) {
    const card = cards[Math.max(0, Math.min(i, cards.length - 1))];
    if (!card) return;
    track.scrollTo({
      left: card.offsetLeft - (track.clientWidth - card.offsetWidth) / 2,
      behavior: smooth && !reduceMotion ? 'smooth' : 'auto'
    });
  }

  function updateCurrent() {                                  // which card is nearest the middle?
    const middle = track.scrollLeft + track.clientWidth / 2;
    let best = 0, bestDistance = Infinity;
    cards.forEach((card, i) => {
      const d = Math.abs(card.offsetLeft + card.offsetWidth / 2 - middle);
      if (d < bestDistance) { bestDistance = d; best = i; }
    });
    current = best;
    cards.forEach((card, i) => card.classList.toggle('current', i === current));
    counter.textContent = `${current + 1} / ${photos.length}`;
    prevBtn.disabled = current === 0;
    nextBtn.disabled = current === photos.length - 1;
  }

  let ticking = false;
  track.addEventListener('scroll', () => {
    if (ticking) return;
    ticking = true;
    requestAnimationFrame(() => { updateCurrent(); ticking = false; });
  });
  prevBtn.addEventListener('click', () => centerOn(current - 1));
  nextBtn.addEventListener('click', () => centerOn(current + 1));
  return {
    next: () => centerOn(current + 1),
    prev: () => centerOn(current - 1),
    reset: () => { centerOn(0, false); updateCurrent(); },
    centerOn, updateCurrent
  };
})();

/* =====================================================================
   7. FULL-SIZE PHOTO VIEWER (lightbox)
   ===================================================================== */
const lightbox = $('#lightbox');
const lightboxFrame = $('#lb-frame');
let lightboxIndex = 0, lightboxOpener = null, lightboxTimer, lightboxSet = 'polaroid';

function openLightbox(index, opener, set = 'polaroid') {
  clearTimeout(lightboxTimer);
  lightboxSet = set;
  lightboxIndex = index;
  lightboxOpener = opener;
  showPhoto(lightboxFrame, PHOTOS[set][index], true);
  lightbox.hidden = false;
  document.body.classList.add('lock');                        // stop the page behind from scrolling
  requestAnimationFrame(() => { lightbox.classList.add('open'); $('#lb-close').focus({ preventScroll: true }); });
}

function stepLightbox(direction) {
  const list = PHOTOS[lightboxSet];
  lightboxIndex = lightboxSet === 'tablet'
    ? wrap(lightboxIndex + direction, list.length)                // the tablet loops, like its own arrows
    : Math.max(0, Math.min(lightboxIndex + direction, list.length - 1));
  showPhoto(lightboxFrame, list[lightboxIndex]);
}

function closeLightbox() {
  lightbox.classList.remove('open');
  lightboxTimer = setTimeout(() => { lightbox.hidden = true; }, reduceMotion ? 0 : 260);
  if (!activeView) document.body.classList.remove('lock');
  if (lightboxSet === 'tablet') tablet.go(lightboxIndex, true);   // tablet shows the photo you ended on
  else { polaroids.centerOn(lightboxIndex, false); polaroids.updateCurrent(); }   // go back to the same Polaroid
  if (lightboxOpener) lightboxOpener.focus({ preventScroll: true });
}

$('#lb-close').addEventListener('click', closeLightbox);
lightbox.addEventListener('click', e => {                     // clicking the dark area (not the photo) closes it
  if (e.target === lightbox || e.target.classList.contains('lb-stage')) closeLightbox();
});

/* =====================================================================
   8. VIEW MANAGER  (open / close the four object views)
   ===================================================================== */
const mainPage = $('#main');
const VIEWS = {
  sketchbook: { el: $('#view-sketchbook'), api: sketchbook, onOpen: () => sketchbook.reset() },
  camera:     { el: $('#view-camera'),     api: camera,     onOpen: () => camera.reset() },
  tablet:     { el: $('#view-tablet'),     api: tablet,     onOpen: () => tablet.reset() },
  polaroid:   { el: $('#view-polaroid'),   api: polaroids,  onOpen: () => polaroids.reset() }
};
let activeView = null, savedScroll = 0, viewOpener = null, hideTimer;

function openView(name, opener) {
  if (activeView) return;
  const view = VIEWS[name];
  clearTimeout(hideTimer);
  activeView = name;
  viewOpener = opener;
  savedScroll = window.scrollY;                               // remember where the main page was
  document.body.classList.add('lock');
  mainPage.inert = true;
  view.el.hidden = false;
  view.onOpen();
  requestAnimationFrame(() => {
    view.el.classList.add('open');
    $('.close', view.el).focus({ preventScroll: true });
  });
}

function closeView() {
  if (!activeView) return;
  const view = VIEWS[activeView];
  view.el.classList.remove('open');
  hideTimer = setTimeout(() => { view.el.hidden = true; }, reduceMotion ? 0 : 320);
  document.body.classList.remove('lock');
  mainPage.inert = false;
  window.scrollTo(0, savedScroll);
  if (viewOpener) viewOpener.focus({ preventScroll: true });
  activeView = null;
}

$$('[data-open]').forEach(button => button.addEventListener('click', () => openView(button.dataset.open, button)));
$$('[data-close]').forEach(button => button.addEventListener('click', closeView));

/* =====================================================================
   9. KEYBOARD:  Esc closes,  left / right arrows browse
   ===================================================================== */
document.addEventListener('keydown', e => {
  if (!lightbox.hidden && lightbox.classList.contains('open')) {          // the full-size viewer comes first
    if (e.key === 'Escape') closeLightbox();
    else if (e.key === 'ArrowRight') stepLightbox(1);
    else if (e.key === 'ArrowLeft') stepLightbox(-1);
    return;
  }
  if (!activeView) return;
  if (e.key === 'Escape') closeView();
  else if (e.key === 'ArrowRight') VIEWS[activeView].api.next();
  else if (e.key === 'ArrowLeft') VIEWS[activeView].api.prev();
});

/* =====================================================================
   10. LEAVING THE PAGE: a quick fade when you go back to the portfolio
   ===================================================================== */
const backLink = $('.back-link');
backLink.addEventListener('click', e => {
  if (reduceMotion) return;
  e.preventDefault();
  document.body.classList.add('leaving');
  setTimeout(() => { window.location.href = backLink.href; }, 260);
});
window.addEventListener('pageshow', () => document.body.classList.remove('leaving'));   // coming back with the browser's Back button